impl officekit_markup_base::Read for EntriesContent {
    fn other(node: Node) -> Option<Self> {
        Some(Self::Other(node))
    }

    fn read(element: &Element) -> Self {
        match officekit_markup_base::name(element) {
            Some((NS_X, "s")) => Self::CharacterValue(officekit_markup_base::read(element)),
            Some((NS_X, "e")) => Self::ErrorValue(officekit_markup_base::read(element)),
            Some((NS_X, "m")) => Self::NoValue(officekit_markup_base::read(element)),
            Some((NS_X, "n")) => Self::Numeric(officekit_markup_base::read(element)),
            _ => Self::Other(Node::Element(element.clone())),
        }
    }
}

impl officekit_markup_base::Write for EntriesContent {
    fn write_into(&self, writer: &mut officekit_markup_base::Writer<'_, '_>) {
        match self {
            Self::CharacterValue(arm) => arm.write_into(writer),
            Self::ErrorValue(arm) => arm.write_into(writer),
            Self::NoValue(arm) => arm.write_into(writer),
            Self::Numeric(arm) => arm.write_into(writer),
            Self::Other(node) => writer.other(node.clone()),
        }
    }
}

